import { getItem, setItem } from 'storage';

export function createOfflineQueue({ storage, send, key = "queue:v1", maxAttempts = 5 }) {
  let queue = [];
  let inFlight = null;

  function loadQueue() {
    try {
      const storedQueue = getItem(key);
      if (Array.isArray(storedQueue)) {
        queue = storedQueue;
      } else {
        queue = [];
      }
    } catch (e) {
      queue = [];
    }
  }

  function saveQueue() {
    setItem(key, JSON.stringify(queue));
  }

  function enqueue(action) {
    if (queue.some(item => item.id === action.id)) return;
    if (action.dedupeKey) {
      const index = queue.findIndex(item => item.dedupeKey === action.dedupeKey);
      if (index !== -1) {
        queue[index] = { ...action, attempts: 0 };
      } else {
        queue.push(action);
      }
    } else {
      queue.push(action);
    }
    saveQueue();
  }

  async function flush() {
    if (inFlight) return inFlight;
    inFlight = (async () => {
      const sent = [];
      const failed = [];
      while (queue.length > 0) {
        const item = queue.shift();
        try {
          const result = await send(item);
          if (result.ok) {
            sent.push(item.id);
          } else if (!result.retryable) {
            failed.push({ id: item.id, reason: "rejected" });
          } else if (item.attempts >= maxAttempts) {
            failed.push({ id: item.id, reason: "max-attempts" });
          } else {
            queue.unshift({ ...item, attempts: item.attempts + 1 });
            break;
          }
        } catch (e) {
          if (e.retryable) {
            queue.unshift({ ...item, attempts: item.attempts + 1 });
            break;
          } else {
            failed.push({ id: item.id, reason: "rejected" });
          }
        }
      }
      saveQueue();
      inFlight = null;
      return { sent, failed, remaining: queue.length };
    })();
    return inFlight;
  }

  function size() {
    return queue.length;
  }

  function peek() {
    return queue.map(item => ({ ...item }));
  }

  loadQueue();
  return { enqueue, flush, size, peek };
}
